async function onLoad(){
  try {

    await Promise.all([
      JS_ShowLoading.run(),
      API_GetPensionerPerson.run(),
      API_GetModalitatiPlata.run(),
      API_FilterCommunicationView.run(),     
      API_GetCalitateReprezentant.run(),
      API_GetCountries.run(),
      API_GetModalitatiPlata.run(),
      API_FilterCommunicationView.run(),
      API_GetDominoRequestByRequestId.run(),
      API_GetDominoRequestByRequestIdAddresa.run(),
      API_GetCurrencies.run(),
      API_FilterPaymentMethodView.run(),
      API_GetViramentPrinBanca.run(),
      API_FilterCountries.run()
    ]);


    const personPaymentView = await API_FilterPersonPaymentView.run();
    if(personPaymentView?.content[0]?.beneficiaryCNS != personPaymentView?.content[0]?.cns) {
      await v_beneficaryCNS.setValue(personPaymentView?.content[0]?.beneficiaryCNS);
    }


    await API_GetAssociatedDominoRequests.run()
    await API_GetAssociatedDominoRequestsModiPlata.run()
    await JS_ClearDefaultValuesDecedati.run()
    await API_SearchByCns.run();

    const currentCTP = await JS_GetCurrentCTP.run();
    const counties = await API_GetCounties.run();

    if(personPaymentView.content[0]?.countyId)
      v_selectedCounty.setValue(counties.find(x => x.name == personPaymentView.content[0]?.countyName));
    else
      v_selectedCounty.setValue(counties.find(x => x.code3 == currentCTP));

    if(personPaymentView.content[0]?.locality){
      const locality = { name: personPaymentView.content[0]?.locality};
      v_selectedLocality.setValue(locality);
    }

    if(personPaymentView.content[0]?.localityFK){
      const localityFK = { code: personPaymentView.content[0]?.localityFK};
      v_selectedLocalityFKcode.setValue(localityFK);
    }

    if(personPaymentView.content[0]?.street){
      const street = { name: personPaymentView.content[0]?.street};
      v_selectedStreet.setValue(street);
    }

    if(personPaymentView.content[0]?.postalOffice){
      const postalOffice = { officeCode: personPaymentView.content[0]?.postalOffice, id: personPaymentView.content[0]?.postalOfficeId};
      v_selectedPostalOffice.setValue(postalOffice);
    }


    await JS_ConverTaraNameInCode.run()
    await JS_SetJudId.run()
    await JS_CererePlataF2SetupVar.run()
    await JS_CererePlataF2SetupVarAdresa.run()
    await JS_BlockDominoF2RadioBtn.run()
    await JS_SameNameAsTitularClear.run()
    await API_SearchByCnsRepTemp.run()
    await API_FindPersonByCnpOP.run() 
    await JS_HideLoading.run()
  } catch {
    console.log("Eroare in onLoad: ", Error )
  } 
}

