async function JS_SetRadioFromDomino() {

  const registryNo = v_cerereModalitatePlata.value;
  if (!registryNo) return;

  // 1) Asigurăm datele necesare (la refresh de obicei sunt încă goale)
  if (!Array.isArray(API_GetAssociatedDominoRequestsModiPlata.data)) {
    await API_GetAssociatedDominoRequestsModiPlata.run();
  }

  if (!Array.isArray(API_GetModalitatiPlata.data)) {
    await API_GetModalitatiPlata.run();
  }

  // 2) Găsim cererea selectată după registryRequestNumber
  const dominoRow =
    API_GetAssociatedDominoRequestsModiPlata.data
      ?.find(r => r.registryRequestNumber === Number(registryNo));

  if (!dominoRow?.paymentMethod) return;

  // 3) Găsim id-ul radio-ului după code (paymentMethod)
  const radioId =
    API_GetModalitatiPlata.data
      ?.find(e => e.code === dominoRow.paymentMethod)
      ?.id;

  if (!radioId) return;

  // 4) Guard: dacă e deja setat corect, nu mai facem nimic
  if (Number(radioModalitatePlata.value) === Number(radioId)) return;

  await radioModalitatePlata.setValue(radioId);
}

