function nullIfEmpty(value) {
  return value === undefined || value === "" ? null : value;
}

async function saveRep () {
  try {
    await v_disableUntilFinishSalveaza.setValue(true)

    const dataCnp = await API_FindPersonByCNPDecedati.run()
    const representant = await API_FilterTemporaryRepresentativeView.run()
    const representantAdresa = await API_FilterTemporaryAddressView.run()

    const payloadTemporaryRepresentative = {
      id : nullIfEmpty(representant?.content[0]?.id ?? null),
      cns: nullIfEmpty(dataCnp?.content[0]?.cns ?? null),
      pensionFileId: nullIfEmpty(v_communication.value.pensionFileId),
      communicationId: nullIfEmpty(v_communication.value.communicationId)
    }

    const payloadTemporaryAddress = {
      id : nullIfEmpty(representantAdresa?.content[0]?.id ?? null),
      streetName: nullIfEmpty(inputReprezentantTemporarStreet.value),
      streetNumber: nullIfEmpty(inputReprezentantTemporarNumber.value),
      building: nullIfEmpty(inputReprezentantTemporarBuilding.value),
      buildingEntrance: nullIfEmpty(inputReprezentantTemporarScara.value),
      floorNumber: nullIfEmpty(inputReprezentantTemporarEtaj.value),
      apartment: nullIfEmpty(inputReprezentantTemporarApartament.value),
      details: nullIfEmpty(inputReprezentantTemporarDetails?.value),
      countryCode: nullIfEmpty(selectTaraTemporaryReprezentant?.value ?? "RO"),
      locality: nullIfEmpty(inputReprezentantTemporarLocality?.value),
      addressCountyName: nullIfEmpty(inputReprezentantTemporarJudet?.value),
      pensionFileId: nullIfEmpty(v_communication.value.pensionFileId),
      communicationId: nullIfEmpty(v_communication.value.communicationId),

      // importante
      addressCountyId: nullIfEmpty(T_CountyIdRepTemp.value),
      localityId: nullIfEmpty(T_LocalityIdFromInputCOM.value),
      streetId: nullIfEmpty(T_StreetIdFromInputCOM.value),
      postalOfficeFK: nullIfEmpty(v_postalCodeIdFromTable.value ?? representantAdresa?.content[0]?.postalOfficeId),
    }

    console.log("payloadTemporaryAddress: ",payloadTemporaryAddress)
    console.log("payloadTemporaryRepresentative: ",payloadTemporaryRepresentative)

    await v_temporaryRepresentative.setValue(payloadTemporaryRepresentative)
    await v_temporaryAddress.setValue(payloadTemporaryAddress)

    if (inputReprezentantTemporarName.value == "") {
      message.error("Detaliile reprezentantului temporar sunt obligatorii")
      return
    } else if (inputReprezentantTemporarPostCode.value == "") {
      message.error("Oficiul postal este obligatoriu")
      return
    } else {
      await API_SaveTemporaryDetails.run()
      message.success("Detaliile de plata au fost salvate cu succes!")  
    }


  } catch {
    console.error(Error)
  } finally {
     await v_disableUntilFinishSalveaza.setValue(false)
  }
}

