async function onInit() {

  try {
    await JS_ShowLoading.run()
    const context = await JS_GetContext.run();
    await v_communication.setValue(context.communication);
    await v_beneficaryCNS.setValue(context?.communication?.cns)

    const [
      existsPensionFilePaymentSdt,
      isComIncetare,
      isNotAllComTermination,
      communication
    ] = await Promise.all([
      API_ExistsPensionFilePaymentSdt.run(),
      API_GetCommunicationTermination.run(),
      API_GetNotAllComTermination.run(),
      API_GetCommunicationById.run()
    ])

    const showTemporaryAddress =
      existsPensionFilePaymentSdt ||
      (isComIncetare > 0 && isNotAllComTermination === 0)

    const showAltaPersoana =
      communication?.communicationType !== 'COM'

    // AFISARE_ADRESA_TEMPORARA
    if (showTemporaryAddress) {
      await v_ajutorDecesCOM.setValue(false)
      await v_ajutorDecesOP.setValue(true)
      const filterTemp = await API_FilterTemporaryRepresentativeView.run()
      const filterAddrss = await API_FilterTemporaryAddressView.run()  
      await API_GetCountries.run()
      await JS_SetJudId.run()
      await JS_HideLoading.run()
      return
    }

    // AFISARE_DETALII_PLATA
    await JS_OnLoad.run()

    await v_ajutorDecesCOM.setValue(true)
    await v_ajutorDecesOP.setValue(false)
    const filterTemp = await API_FilterTemporaryRepresentativeView.run()
    const filterAddrss = await API_FilterTemporaryAddressView.run()
    await v_tempRep.setValue(filterTemp)

    // sectiune Plata alta persoana (doar OP)
    if (showAltaPersoana) {
      await API_FilterCountiesDecedati.run()
      await v_plataAltaPersoanaCheckboxDisable.setValue(false)
      await JS_IsAltaPersoanaDefaultCheckbox.run()
      await JS_CheckboxAltaPersoana.run()
    } else {
      await v_plataAltaPersoanaCheckboxDisable.setValue(true)
    }

  } catch {
    console.log("eroare pe OnInit")
  }

}

onInit()

