async function preiaAdresa() {
  await v_preluareAdresaDomiciliuLoading.setValue(true)
  const persoanaFromCNP = await API_FindPersonByCNP.run()
  await v_preluareAdresaDomiciliu.setValue(persoanaFromCNP.content[0].cns)
  await JS_PreluareAdresaRunNonTitular.run()
}

preiaAdresa()

async function preluareAdresa() {
  const cnsData = await API_SearchByCnsNonTitular.run()
  selectTaraCorespondentaTitular.setValue(cnsData[0].countryCode);
  await inputContainerTitularCorespondentaJudet.setValue(cnsData[0].county);
  inputContainerTitularCorespondentaLocalitate.setValue(cnsData[0].locality);
  inputContainerTitularCorespondentaStrada.setValue(cnsData[0].street);
  inputContainerTitularCorespondentaNr.setValue(cnsData[0].streetNumber);
  inputContainerTitularCorespondentaBloc.setValue(cnsData[0].building);
  inputContainerTitularCorespondentaScara.setValue(cnsData.entrance);
  inputContainerTitularCorespondentaEtaj.setValue(cnsData.floor);
  inputContainerTitularCorespondentaApartament.setValue(cnsData.apartment);
  inputContainerTitularCorespondentaOP.setValue(null)
  inputContainerTitularCorespondentaCTP.setValue(null) 
  await v_preluareAdresaDomiciliuLoading.setValue(false)
}

preluareAdresa()

transformers.script:
if(!v_selectedStreet.value?.name)
  return "";

if(!v_selectedStreet.value?.streetPrefix)
  return v_selectedStreet.value?.name;

return v_selectedStreet.value?.streetPrefix + " " +v_selectedStreet.value?.name

const inputExportIsraelExportCodOISNumber = Number(inputExportIsraelExportCodOIS.value)

const payload = {
    "cns": v_communication.value.cns,
    "pensionFileId": v_communication.value.pensionFileId,
    "communicationId": v_communication.value.communicationId,
    "paymentTypeId": radioModalitatePlata.value
  };

if(T_ModalitatePlata.value.code == 'PL_CNPR')
{
  payload.justifyingDetails = inputMandatDetaliiCTP.value;
  payload.iban = "-",
  payload.bankingInstitution = "-"
}
else if(T_ModalitatePlata.value.code == 'PL_VRB_ROM')
{
  payload.iban = inputIBAN.value;
  payload.bankingInstitution = inputBanca.value;
  payload.justifyingDetails = inputViramentDetaliiCTP.value;
}
else if(T_ModalitatePlata.value.code == 'PL_VRB_STR')
{
  payload.iban = inputExportPrestatiiStrainatateIBAN.value;
  payload.bankingInstitution = inputExportPrestatiiStrainatateCatreBanca.value;
  payload.justifyingDetails = inputExportPrestatiiStrainatateDetaliiCTP.value;
  payload.swiftCode = inputExportPrestatiiStrainatateSWIFT.value;
  payload.bankAddress = inputExportPrestatiiStrainatateAdresa.value;
  payload.currencyId = selectExportPrestatiiStrainatateMoneda.value;
  payload.personName = inputExportPrestatiiStrainatateNume.value;
  payload.country = selectExportPrestatiiStrainatateTara.value;
  payload.fullNameEU = inputExportPrestatiiStrainatateNumeTitular.value;
  payload.cnpEU = inputExportPrestatiiStrainatateCNP.value;
  payload.transferTypeId = API_GetViramentPrinBanca.data.find(x => x.code == selectExportPrestatiiPrinBancaSTR.value).id;
}
else if(T_ModalitatePlata.value.code == 'PL_VRB_STR_I')
{
  payload.iban = inputExportIsraelExportIBAN.value;
  payload.bankingInstitution = inputExportIsraelExportCatre.value;
  payload.justifyingDetails = inputExportIsraelExportDetaliiCTP.value;
  payload.bankBranch = inputExportIsraelExportSucursala.value;
  payload.swiftCode = inputExportIsraelExportSWIFT.value;
  payload.bankAddress = inputExportIsraelExportAdresaBanca.value;
  payload.accountNumber = inputExportIsraelExportCodOIS.value
  payload.transferTypeId = API_GetViramentPrinBanca.data.find(x => x.code == selectExportPrestatiiPrinBancaISR.value).id;
}

return payload;

